### Reserve generated form identifiers

**Severity:** `high`

The collector generates `form-0`, `form-1`, and so on without accounting for explicit IDs supplied by the author. An explicit `form-0` followed by an omitted ID therefore registers two handlers under the same key, and the later handler replaces the first one. Track allocated and registered IDs together, skip every reserved ID when generating a new one, and reject duplicate explicit registrations so nested forms cannot route submissions to the wrong handler.

```suggestion
function createFormCollector(scope: PageScope): FormCollector {
  let counter = 0;
  const allocatedIds = new Set<string>();
  const registeredIds = new Set<string>();
  return {
    nextId(): string {
      while (allocatedIds.has(`form-${String(counter)}`) || registeredIds.has(`form-${String(counter)}`)) {
        counter += 1;
      }
      const id = `form-${String(counter)}`;
      counter += 1;
      allocatedIds.add(id);
      return id;
    },
    register(formId: string, handler: FormSubmitHandler): void {
      if (registeredIds.has(formId)) {
        throw new Error(`Duplicate form id: ${formId}`);
      }
      if (allocatedIds.has(formId)) {
        allocatedIds.delete(formId);
      }
      registeredIds.add(formId);
      scope.forms.set(formId, handler);
    },
  };
}
```
